-- Agenda do Sentinela (fila contínua) e do Radar (janela diária). Registro do que foi aplicado em produção.
SELECT cron.schedule('nga-lab-sentinela', '* * * * *', $job$SELECT net.http_post(url := 'https://ndwgzqkbxnjkkkbguytm.supabase.co/functions/v1/nga-lab-api/interno/rotina/sentinela', headers := jsonb_build_object('x-nga-rotina', (SELECT token FROM nga_lab.rotina_chave), 'content-type', 'application/json'), body := '{}'::jsonb, timeout_milliseconds := 140000)$job$);
SELECT cron.schedule('nga-lab-radar', '* 10-12 * * *', $job$SELECT net.http_post(url := 'https://ndwgzqkbxnjkkkbguytm.supabase.co/functions/v1/nga-lab-api/interno/rotina/radar', headers := jsonb_build_object('x-nga-rotina', (SELECT token FROM nga_lab.rotina_chave), 'content-type', 'application/json'), body := '{}'::jsonb, timeout_milliseconds := 60000)$job$);
